import Foundation
import CoreGraphics
var passed = 0, failed = 0
func check(_ name: String, _ value: Bool) {
    if value { passed += 1; print("PASS \(name)") }
    else { failed += 1; print("FAIL \(name)") }
}
// Recovery/absence proof for only the suite generated by the retained runner.
// This path never creates a progression singleton or accesses .standard.
if CommandLine.arguments.contains("--cleanup-suite") {
    guard CommandLine.arguments.contains("--private-suite"), let backing = ProbeContext.backing else {
        print("CLEANUP INVALID"); exit(2)
    }
    ProbeContext.clean()
    let absent = backing.persistentDomain(forName: ProbeContext.name) == nil
    print("CLEANUP \(ProbeContext.name) \(absent ? "ABSENT" : "PRESENT")")
    exit(absent ? 0 : 1)
}
let store = ProbeContext.store // Explicit memory/private suite before any manager singleton.
defer { ProbeContext.clean() }
let preserved: [String: Any] = ["sf_sfxEnabled": false, "sf_bgmEnabled": true,
    "sf_bannedFamily": "Frost", "sparkforge_ads_removed": true,
    "sparkforge_owned_products": ["probe-owned-product"], "probe_unrelated_setting": 42]
for (key, value) in preserved { store.set(value, forKey: key) }
let bossIDs = ["slag_titan", "quench_warden", "dynamo_choir", "faceted_lie", "unmade_star", "marchwarden", "switchwarden"]
// Saved data, not an unknown-boss registration call (which asserts in DEBUG).
store.set(bossIDs + ["unregistered_probe_only"], forKey: "sf_defeated_bosses")
store.set(6, forKey: "sf_current_arena")
store.set(1, forKey: "sf_arenas_unlocked")
for key in ["sf_melee_kills", "sf_ranged_kills", "sf_boss_kills", "sf_quench_kills", "sf_warden_kills", "sf_coilworks_kills", "sf_choir_kills", "sf_mirrorwound_kills"] { store.set(100, forKey: key) }
store.set(200.0, forKey: "sf_longest_survival"); store.set(true, forKey: "sf_survived_2min")
store.set(55, forKey: "sf_forge_xp"); store.set(3, forKey: "sf_forge_level")
let manager = ProgressionManager.shared
check("ER01 seven production arena identities unchanged", ArenaConfig.all.map { $0.id } == Array(0...6) && ArenaConfig.all.map { $0.bossID } == bossIDs)
check("ER02 seven Boss Mode pairings unchanged", BossRegistry.shared.all.map { $0.id } == bossIDs && BossRegistry.shared.all.map { $0.arenaID } == Array(0...6))
check("ER03 full roster debug bypass disabled", !GameConfig.BossMode.debugForceFullRoster)
check("ER04 actual launch reconciliation opens earned registered arenas", manager.arenasUnlocked == 7 && manager.currentArena == 6)
check("ER05 seeded ledger earns actual registry roster", BossRegistry.shared.unlocked.map { $0.id } == bossIDs)
check("ER06 unknown saved ledger string creates no registry entry", ArenaConfig.arena(forBossID: "unregistered_probe_only") == nil && BossRegistry.shared.entry("unregistered_probe_only") == nil)
manager.registerArenaBossDefeat("switchwarden")
check("ER07 terminal registered victory cannot expose Arena8", manager.arenasUnlocked == 7 && ArenaConfig.all.count == 7)
manager.resetAll()
check("ER08 reset removes raw defeat ledger key", store.object(forKey: "sf_defeated_bosses") == nil)
check("ER09 reset clears interpreted recorded defeats", manager.defeatedBosses.isEmpty)
check("ER10 reset removes all legacy gate counters", [manager.totalKills, manager.quenchKills, manager.wardenKills, manager.coilworksKills, manager.choirKills, manager.mirrorwoundKills].allSatisfy { $0 == 0 })
check("ER11 reset removes legacy boss fallback eligibility", bossIDs.allSatisfy { !manager.hasDefeatedBoss($0) })
check("ER12 reset returns arena access and selection to defaults", manager.arenasUnlocked == 1 && manager.currentArena == 0 && ArenaConfig.current.id == 0)
check("ER13 reset removes survival and forge progress", manager.longestSurvival == 0 && !manager.hasSurvived2Minutes && manager.forgeXP == 0 && manager.forgeLevel == 0)
check("ER14 reset preserves complete nonprogress profile", NSDictionary(dictionary: ProbeContext.snapshot()).isEqual(to: preserved))
check("ER15 actual shared registry roster relocks", BossRegistry.shared.unlocked.isEmpty && !BossRegistry.shared.isAvailable)
let relaunched = ProgressionManager()
check("ER16 recreated manager cannot resurrect arena access", relaunched.arenasUnlocked == 1 && relaunched.currentArena == 0)
check("ER17 recreated manager cannot resurrect boss eligibility", bossIDs.allSatisfy { !relaunched.hasDefeatedBoss($0) } && relaunched.defeatedBosses.isEmpty)
check("ER18 reset calls existing forge collaborator once", ResetCalls.forge == 1)
manager.resetAll()
check("ER19 repeated reset is idempotent on complete profile", NSDictionary(dictionary: ProbeContext.snapshot()).isEqual(to: preserved))
store.set(["switchwarden", "unregistered_probe_only"], forKey: "sf_defeated_bosses")
store.set(7, forKey: "sf_arenas_unlocked"); store.set(6, forKey: "sf_current_arena")
manager.eraseAllProgress()
check("ER20 public erase removes raw recorded victories", store.object(forKey: "sf_defeated_bosses") == nil)
check("ER21 public erase relocks actual Boss Mode roster", BossRegistry.shared.unlocked.isEmpty)
let erasedRelaunch = ProgressionManager()
check("ER22 public erase survives launch reconciliation", erasedRelaunch.arenasUnlocked == 1 && erasedRelaunch.defeatedBosses.isEmpty)
check("ER23 public erase preserves settings and purchase values", NSDictionary(dictionary: ProbeContext.snapshot()).isEqual(to: preserved))
check("ER24 public erase keeps collaborator dispatch", ResetCalls.forge == 3 && ResetCalls.scores == 1 && ResetCalls.codex == 1 && ResetCalls.daily == 1)
manager.eraseAllProgress()
check("ER25 repeated public erase stays empty and preserves profile", manager.defeatedBosses.isEmpty && NSDictionary(dictionary: ProbeContext.snapshot()).isEqual(to: preserved))
manager.registerArenaBossDefeat("slag_titan")
check("ER26 legitimate new victory records after erase", manager.defeatedBosses == Set(["slag_titan"]))
check("ER27 legitimate new victory opens only existing next arena", manager.arenasUnlocked == 2 && BossRegistry.shared.unlocked.map { $0.id } == ["slag_titan"])
manager.currentArena = 7; manager.arenasUnlocked = 8
check("ER28 stale future selection cannot reach an eighth registry arena", ArenaConfig.current.id == 6 && ArenaConfig.all.count == 7 && manager.currentArena == 7)
manager.resetAll()
check("ER29 final reset leaves only preserved nonprogress values", NSDictionary(dictionary: ProbeContext.snapshot()).isEqual(to: preserved))
check("ER30 final recreated manager and shared roster stay locked", ProgressionManager().arenasUnlocked == 1 && BossRegistry.shared.unlocked.isEmpty)
print("Arena8 Progression Boundary: \(passed) passed / \(failed) failed")
ProbeContext.clean() // Explicit cleanup before C exit; defer is not the only cleanup path.
exit(failed == 0 ? 0 : 1)
